import type {
  Timeseries,
  TimeseriesDatapoint,
} from '../../charts/core/types/timeseries.js';
import { mulberry32 } from '../../core/utils/seed-random.js';
import { uuidv4 } from '../../core/utils/uuidv4.js';

const TIMESERIES_CHART_SELECTED_DATE = new Date('Mon Feb 22 2021 11:30:00 UTC');

const DATAPOINT_RESOLUTION = 3_600_000;

/**
 * Generates timebased randomized datapoints typed as an array of TimeseriesDatapoint objects
 * One datapoint = -1h in time starting from current timestamp, spanning 59 minutes
 */
export const generateMockTimeseriesDatapoints = (options: {
  /** How many datapoints should be generated in a given series @defaultValue 10 */
  datapointsPerSeries?: number;
  /** Minimum Y value for the mock data. @defaultValue 0 */
  minY?: number;
  /** Maximum Y value for the mock data. @defaultValue 300_000 */
  maxY?: number;
  /**
   * Seed to use for the random function.
   */
  seed?: number;
  /** Whether datapoints are homogenous. This means each datapoint is equal in time length. @defaultValue false */
  hasHomogenousDatapoints?: boolean;
  /** If provided will generate random gaps of the given maximum length in ms in the resulting datapoints */
  randomGapMaxDuration?: number;
}): TimeseriesDatapoint[] => {
  const {
    seed,
    hasHomogenousDatapoints,
    datapointsPerSeries = 10,
    minY = 0,
    maxY = 300_000,
    randomGapMaxDuration,
  } = options;

  const timeseriesDatapoints: TimeseriesDatapoint[] = [];
  // If a seed is given, provide a seeded random function to achieve testable
  // results.
  const random = seed !== undefined ? mulberry32(seed) : Math.random;
  // If a seed is given, assume a fixed point in time as now to achieve testable
  // results.
  let now =
    seed !== undefined ? TIMESERIES_CHART_SELECTED_DATE.getTime() : Date.now();

  if (hasHomogenousDatapoints) {
    now += random() * (DATAPOINT_RESOLUTION * 2);
  }

  let index = 0;

  while (index < datapointsPerSeries) {
    const timeResolution = hasHomogenousDatapoints
      ? random() * DATAPOINT_RESOLUTION
      : DATAPOINT_RESOLUTION;

    timeseriesDatapoints.push({
      start: new Date(now),
      end: new Date(now + timeResolution),
      value: Math.floor(random() * (maxY - minY + 1)) + minY,
    });

    now += timeResolution;
    if (randomGapMaxDuration && randomGapMaxDuration > 0 && index > 1) {
      const hasNonConsecutiveGap = Boolean(Math.round(random() * 1));
      now += hasNonConsecutiveGap ? random() * randomGapMaxDuration * 60 : 0;
    }

    index++;
  }

  return timeseriesDatapoints;
};

/**
 * Generates random timeseries chart data.
 */
export const generateMockTimeseries = (options: {
  /**
   * The number of mock timeseries generated.
   * @defaultValue 10
   */
  numberOfSeries?: number;
  /**
   * The number of mock datapoints generated per timeseries.
   * @defaultValue 10
   */
  datapointsPerSeries?: number;
  /**
   * Seed to use for the random function.
   */
  seed?: number;
  /**
   * The unit used for the mock timeseries.
   * @defaultValue 'kbit/s'
   */
  unit?: string;
}): Timeseries[] => {
  const {
    numberOfSeries = 10,
    datapointsPerSeries = 10,
    seed,
    unit = 'kbit/s',
  } = options;
  return new Array(numberOfSeries).fill(null).map(() => {
    const id = uuidv4(seed);
    return {
      id,
      name: id,
      unit,
      datapoints: generateMockTimeseriesDatapoints({
        datapointsPerSeries,
        seed,
      }),
    };
  });
};
